\label{defi1}Set $\zeta=3$ for the capillary driven flow ($\mathcal{S}>0$) and $\zeta=1$ for the gravity driven flow ($\mathcal{S}=0$).We say that $(f,\Theta)\in \left(L^1(0,T;W^{\zeta,1}({\mathbb T}))\right)^2$ is a weak solution of (\ref{eq:systemlinearized}) on $[0,T)$ corresponding to initial data $(f_0,\Theta_0)$ if and only if
\begin{align*}
-\int_{\mathbb T} f_0\phi(0)dx&-\int_0^T\int_{\mathbb T} f\partial_t\phi dxdt+\int_0^T\int_{\mathbb T} \partial_x^2\phi\left(-\frac{h_\sharp^2}{2}\Theta +\left(\frac{\mathcal{A}}{h_\sharp}-\frac{\mathcal{G}}{3}h_\sharp^3\right)f\right)  dxdt\\
&+\int_0^T\int_{\mathbb T}\partial_x^4\phi \frac{\mathcal{S}}{3}h_\sharp^3f dxdt+\sum_{j=1}^4\int_0^T\int_{\mathbb T}  \partial_x^{-1}N_j\partial_x \phi dxdt =0
\end{align*}
and
\begin{align*}
-\int_{\mathbb T} \Theta_0\psi(0)dx&-\int_0^T\int_{\mathbb T} \Theta\partial_t\psi dxdt+\int_0^T\int_{\mathbb T} \partial_x^2\psi\left(-\left(h_\sharp\Gamma_\sharp+\mathcal{D}\right)\Theta+\left(\frac{3\mathcal{A}\Gamma_\sharp}{2h_\sharp^2}-\frac{\mathcal{G}}{2}\bGh_\sharp^2\right)f\right)  dxdt\\
&+\int_0^T\int_{\mathbb T}\partial_x^4\psi\frac{\mathcal{S}}{2} \bGh_\sharp^2f dxdt+\sum_{j=5}^8\int_0^T\int_{\mathbb T}  \partial_x^{-1}N_j\partial_x \psi dxdt =0
\end{align*}
for all $(\phi,\psi)\in C^{\infty}_c([0,T)\times {\mathbb T})$,  where $\partial_x^{-1}$ denotes the operator given by $\widehat{\partial_x^{-1}u}(n)=-\frac{i}{n}\hat{u}(n)$.

\label{global1}
Let $f_0\in \dot A^0({\mathbb T}), \Theta_0\in \dot A^0({\mathbb T})$ be nontrivial  initial data for \eqref{eq:systemlinearized}
such that
$$
\mathscr{E}^0_0(f_0,\Theta_0)<\min\{h_\sharp,\Gamma_\sharp\}.
$$
Assume that $\mathfrak{C}_1,\mathfrak{C}_2>0$. If
\begin{align*}
\gamma_1:=\mathfrak{C}_1-\Lambda_1(0)\mathscr{E}_0^0(f_0,\Theta_0)&>0,\\
\gamma_2:=\mathfrak{C}_2-\Lambda_2(0)\mathscr{E}_0^0(f_0,\Theta_0)&>0,
\end{align*}
then there exists at least one global solution $(f,\Theta)$ of \eqref{eq:systemlinearized} in the sense of Definition \ref{defi1} with regularity
\begin{align*}
(f,\Theta)\in &\Big(L^{\frac{2}{r}}\left(0,T;W^{r,\infty}({\mathbb T})\right)\cap L^1\left(0,T;C^{1+\alpha}({\mathbb T})\right) \cap L^2(0,T;H^2({\mathbb T}))\Big)^2,
\end{align*}
for any $r\in[0,2), \alpha\in[0,\frac{1}{2})$ and $T>0$. Moreover, the weak solution satisfies the following exponential decay:
$$
\|f(t)\|_{L^\infty}+\|\Theta(t)\|_{L^\infty}\leq \mathscr{E}^0_0(f_0,\Theta_0)e^{-\delta t},
$$
where 
\begin{equation}\label{delta2}
\delta=\min\{\gamma_1,\gamma_2\}>0.
\end{equation}
Furthermore, if the solution $(f,\Theta)$ satisfies the regularity
$$
(f,\Theta)\in \left(L^1\left(0,T;\dot{A}^2({\mathbb T})\right)\right)^2,
$$
then the weak solution is unique.

\label{global2} 
